// ===== 泛型接口：类型参数出现在多个位置 =====
interface ApiResponse<T> {
  code: number;
  message: string;
  data: T;
}
interface User { id: number; name: string; }
type UserResponse = ApiResponse<User>; // data 的类型是 User

// ===== 泛型类：栈，类型参数约束内部存储和取出的类型 =====
class Stack<T> {
  private items: T[] = [];
  push(item: T) { this.items.push(item); }
  pop(): T | undefined { return this.items.pop(); } // 返回 T | undefined，连接了 push 的类型
  peek(): T | undefined { return this.items[this.items.length - 1]; }
  get size(): number { return this.items.length; }
}
const numStack = new Stack<number>();
numStack.push(1);
const top: number | undefined = numStack.peek(); // 类型安全

// ===== 手写 Partial：映射类型给每个键加 ? =====
type MyPartial<T> = { [K in keyof T]?: T[K] };

type MyRequired<T> = { [K in keyof T]-?: T[K] }; // -? 移除可选

// ===== 手写 Pick：K 约束为 T 的键子集 =====
type MyPick<T, K extends keyof T> = { [P in K]: T[P] };

// ===== 手写 Omit：Pick + Exclude 组合 =====
type MyOmit<T, K extends keyof T> = Pick<T, Exclude<keyof T, K>>;

// ===== 手写 Record：键联合 K 映射到统一类型 V =====
type MyRecord<K extends keyof any, V> = { [P in K]: V };

// ===== 条件类型 + infer：提取函数返回类型 =====
type MyReturnType<T> = T extends (...args: any[]) => infer R ? R : never;
type R1 = MyReturnType<() => string>; // string

// ===== 条件类型 + infer：提取函数第一个参数 =====
type FirstParam<T> = T extends (first: infer P, ...rest: any[]) => any ? P : never;
type P1 = FirstParam<(a: string, b: number) => void>; // string

// ===== 条件类型 + infer：提取 Promise 内部类型 =====
type UnwrapPromise<T> = T extends Promise<infer U> ? U : T;
type U1 = UnwrapPromise<Promise<string>>; // string
type U2 = UnwrapPromise<number>;           // number

// ===== 递归条件类型：解包嵌套 Promise =====
type DeepAwaited<T> = T extends Promise<infer U> ? DeepAwaited<U> : T;
type D = DeepAwaited<Promise<Promise<Promise<string>>>>; // string

// ===== 分布式条件类型：联合成员分别求值 =====
type ToArray<T> = T extends any ? T[] : never;
type Distributed = ToArray<string | number>; // string[] | number[]
// 如果想整体求值，用 [T] 包装：
type NonDistributive<T> = [T] extends [any] ? T[] : never;
type NonDist = NonDistributive<string | number>; // (string | number)[]

// ===== 实际场景：API 分页响应 =====
interface Paginated<T> { items: T[]; total: number; page: number; }
type UserList = Paginated<User>; // items: User[]
type UserSummary = Paginated<Pick<User, 'id' | 'name'>>; // 只要 id 和 name
